					... on ModeConfiguration {
						order
						friendlyName {
							type
							value {
								text
								locale
							}
						}
						modeOptions {
							value
							modeResources {
								friendlyName {
									type
									value {
										text
										locale
									}
								}
							}
						}
					}
					... on RangeConfiguration {
						supportedRange {
							minimumValue
							maximumValue
							precision
						}
						friendlyName {
							type
							value {
								text
								locale
							}
						}
						unitOfMeasure {
							type
							value {
								text
								locale
							}
						}
						presets {
							rangeValue
							presetResources {
								friendlyName {
									type
									value {
										text
										locale
									}
								}
							}
						}
					}
				}
