						timeOfSample
						timeOfLastChange
						type
						armStateValue
						error {
							type
							message
						}
					}
					... on Battery {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
						batteryValue {
							levelPercentage
							chargingHealth {
								state
								reason
							}
							health {
								state
								reasons
							}
