					... on BurglaryAlarm {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						burglaryAlarmValue
						error {
							type
							message
						}
					}
					... on CarbonMonoxideAlarm {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						carbonMonoxideAlarmValue
					}
					... on Color {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						colorStateValue {
							hue
							saturation
							brightness
						}
					}
					... on ColorTemperature {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						colorTemperatureInKelvinStateValue
					}
