						timeOfLastChange
						accuracy
						type
						powerLevelValue
						error {
							type
							message
						}
					}
					... on Power {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						powerStateValue
						error {
							type
							message
						}
					}
					... on Percentage {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						percentageValue
						error {
							type
							message
						}
