						timeOfSample
						timeOfLastChange
						accuracy
						type
						lockState
						error {
							type
							message
						}
					}
					... on DetectionState {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						detectionStateValue
						error {
							type
							message
						}
					}
					... on Illuminance {
						name
						accuracy
						type
						timeOfSample
						timeOfLastChange
						error {
							type
							message
						}
