							value
						}
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
					}
					... on ToggleState {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						toggleStateValue
						error {
							type
							message
						}
					}
					... on ThermostatMode {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						thermostatModeValue
						error {
							type
							message
						}
					}
					... on TemperatureSensor {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						error {
							type
							message
						}
						value {
							value
							scale
						}
					}
					... on StatusCode {
						name
						type
						accuracy
						timeOfSample
						timeOfLastChange
						statusCodeValue {
							value {
								code
								timeOfDetection
							}
						}
						error {
							type
							message
						}
					}
					... on Snapshot {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
						snapshotValue {
							uri
							uriExpirationTime
							authenticationType
						}
					}
					... on SirenState {
						name
						accuracy
						timestamp
						timeOfSample
						timeOfLastChange
						type
						error {
							type
							message
						}
						sirenStateValue {
							state
							playlistId
							playOrder {
								assetId
								loopCount
								loopPauseInMilliseconds
							}
						}
					}
					... on Setpoint {
						name
						timestamp
						timeOfSample
						timeOfLastChange
						accuracy
						type
						deviceNativeScaleValue
						error {
							type
							message
						}
						value {
							value
							scale
						}
					}
					... on RelativeHumidity {
						name
						accuracy
						type
						timeOfSample
						timeOfLastChange
						error {
							type
							message
						}
						relativeHumidityValue {
							value
						}
					}
				}
				operations {
					name
				}
				featureOperations {
					name
				}
			}
			displayCategories {
				all {
					isCustomerSpecified
					isDiscovered
					sources
					value
				}
				primary {
					isCustomerSpecified
					isDiscovered
					sources
					value
				}
			}
			model {
				type
				value {
					text
					locale
				}
			}
			manufacturer {
				type
				value {
					text
					locale
				}
			}
			serialNumber {
				type
				value {
					text
					locale
				}
			}
			description {
				type
				value {
					text
					locale
				}
			}
			dmsIdentifier {
				deviceType
				dsn
			}
		}
